// ---------------- meteor ----------------
// d = head_x - pixel_x in whole pixels: the tail lies 0..127 px behind the
// head. dyq = pixel_y - track_y (Q4), track slope 1/8 (2 Q4 per pixel).
// shape = tail (linear fade towards the tail end x thin cross-section) +
// soft head; one multiply by the frame's envelope gives the meteor light.
reg m_on;
reg [7:0] m_env;
reg signed [11:0] m_d0;
reg [12:0] m_hy;
reg signed [11:0] m_d;
reg signed [15:0] m_dy;
always @(posedge I_clk or posedge I_rst) begin
    if(I_rst) begin
        m_on<=0; m_env<=0; m_d0<=0; m_hy<=0; m_d<=0; m_dy<=0;
    end else begin
        if(frame_start) begin
            m_on<=I_meteor_on && I_meteor_env!=0; m_env<=I_meteor_env;
            m_d0<=I_meteor_x_q4[15:4]-VIEW_X;
            m_hy<=I_meteor_y_q4;
        end
        if(prep) begin
            m_d<=m_d0;
            m_dy<=$signed({2'd0,prep_y,4'd0})-$signed({3'd0,m_hy})+$signed({m_d0[11],m_d0,3'd0})/4;
        end else if(I_de) begin
            m_d<=m_d-12'sd1; m_dy<=m_dy-16'sd2;
        end
