wire signed [11:0] n_d =I_de ? m_d-12'sd1 : m_d;
wire signed [15:0] n_dy=I_de ? m_dy-16'sd2 : m_dy;
wire [15:0] ady_w=n_dy[15] ? -n_dy : n_dy;
wire        near_track=ady_w<16'd48;
wire [5:0]  ady=ady_w[5:0];
wire        tail_ok=m_on && !n_d[11] && n_d<=12'sd127 && ady<6'd24 && near_track;
wire [6:0]  tail_len=7'd127-n_d[6:0];
wire [14:0] tail_p=tail_len*gc_meteor(ady[4:1]);
wire [7:0]  tail_s=tail_ok ? tail_p[14:7] : 8'd0;
wire [11:0] ad_w=n_d[11] ? -n_d : n_d;
wire        head_ok=m_on && ad_w<=12'd2 && near_track;
wire [5:0]  adx16={ad_w[1:0],4'd0};
wire [5:0]  hmax=adx16>ady ? adx16 : ady;
wire [5:0]  hmin=adx16>ady ? ady : adx16;
wire [6:0]  hr={1'b0,hmax}+{2'd0,hmin[5:1]};
wire [7:0]  head_s=(head_ok && hr<7'd76) ? gb_meteor(hr[6:2]) : 8'd0;
wire [8:0]  m_shape={1'b0,tail_s}+{1'b0,head_s};
wire [15:0] m_p=m_env*(m_shape[8] ? 8'd255 : m_shape[7:0]);
wire [7:0]  m_v=m_p[15:8];

// ---------------- colour and blend ----------------
function [23:0] tint_far;
    input [7:0] v; input [1:0] t;
    begin case(t)
        2'd0: tint_far={v,v,v};
        2'd3: tint_far={(v>>1)+(v>>3), v-(v>>2), v};                 // pale blue
        default: tint_far={v-(v>>2), v-(v>>3), v};                   // cool white
    endcase end
endfunction
function [23:0] tint_near;
    input [7:0] v; input [1:0] t;
    begin case(t)
        2'd0: tint_near={v,v,v};                                     // white
        2'd1: tint_near={v-(v>>2)+(v>>5), v-(v>>3), v};              // blue-white
        2'd2: tint_near={v, v-(v>>3)+(v>>5), (v>>1)+(v>>3)+(v>>4)};  // yellow-white
        default: tint_near={v, v-(v>>2)+(v>>4), (v>>1)+(v>>4)};      // soft orange
    endcase end
endfunction
