localparam integer CELL=1<<CELL_BITS;
localparam integer NB=2*R+1;
localparam integer OXB=(NEAR ? 128 : 64);       // first allowed star x (Q4)

// ---- frame constants ----
reg [6:0] c0; reg [4:0] kp0; reg [3:0] l0;
wire signed [16:0] sx_raw=$signed(VIEW_X*16)-$signed({2'd0,off_q4});
wire [14:0] sx0=sx_raw[16] ? sx_raw[14:0]+15'd20480 : sx_raw[14:0];
