reg [7:0] buf1 [0:NB-1];
reg [4:0] kb0, kb1; reg [1:0] tn0, tn1; reg ex0, ex1;
// ---- pixel state: slot in cell, cell index, which slot is shown ----
reg [4:0] kp; reg [6:0] col; reg ptr;
wire last_px=kp==CELL-1;
wire [4:0] n_kp =de ? (last_px ? 5'd0 : kp+1'b1) : kp;
wire       n_ptr=de && last_px ? ~ptr : ptr;
wire [4:0] i0=n_kp-kb0, i1=n_kp-kb1;
wire [7:0] v0=(ex0 && i0<NB) ? buf0[i0] : 8'd0;
wire [7:0] v1=(ex1 && i1<NB) ? buf1[i1] : 8'd0;
