reg [6:0]  jcell; reg jset;
reg        pend; reg [6:0] pcell; reg pset;
reg [15:0] h1, h2;
reg [15:0] ma, mb; reg [31:0] prod;
reg [7:0]  sa, sb;  reg [15:0] sprod;
always @(posedge clk) begin prod<=ma*mb; sprod<=sa*sb; end
reg        jex, spark;
reg [8:0]  ox_q4;
reg [4:0]  oy;
reg [7:0]  bri, beff, bc, bs;
reg [1:0]  tint;
reg [5:0]  ady; reg dy0;
reg [4:0]  kb, e;
wire [15:0] seed={SALT,cy,jcell[6:0]} ^ 16'h0000;
wire [15:0] hx1=seed^(seed>>8);
wire [15:0] h1w=prod[15:0]^(prod[15:0]>>9);
wire [15:0] h2w=prod[31:16]^prod[15:0];
