wire signed [6:0] dy=$signed({2'd0,ly})-$signed({2'd0,oy});
wire [9:0]  kc_num={1'b0,ox_q4}-{6'd0,l0}+10'd8;
wire [4:0]  slot=kb+e;
wire signed [10:0] dxq=$signed({2'd0,l0}+{2'd0,slot,4'd0})-$signed({2'd0,ox_q4});
