wire [7:0]  gx=NEAR ? gx_near(axi) : gx_far(axi[4:0]);
wire [7:0]  gy=NEAR ? gy_near(ady[2:0]) : gy_far(ady[2:0]);
wire [7:0]  sp=dy0 ? sh_near(axi) : sn_near(axi);
wire [8:0]  vsum={1'b0,prod[15:8]}+(NEAR ? {1'b0,sprod[15:8]} : 9'd0);
wire [7:0]  vsat=vsum[8] ? 8'd255 : vsum[7:0];

always @(*) begin
    ma=0; mb=0; sa=0; sb=0;
    case(st)
        5'd1: begin ma=hx1;                 mb=16'hA3D3; end
        5'd2: begin ma=prod[15:0]^(prod[15:0]>>7); mb=16'h4B2D; end
        5'd3: begin ma=h1w^16'h9E37;        mb=16'h6F4B; end
        5'd4: begin ma={8'd0,h2w[7:0]};     mb={8'd0,h2w[7:0]}; end
        5'd5: begin ma={8'd0,tw_fac};       mb={8'd0,fade_l}; end
        5'd6: begin ma={8'd0,bri};          mb={8'd0,prod[15:8]}; end
        5'd7: begin ma={8'd0,prod[15:8]};   mb={8'd0,gy};
                    sa=prod[15:8]; sb=dy0 ? 8'd115 : sv_near(ady[2:0]); end
        default: if(st>=5'd9) begin
                    ma={8'd0,bc}; mb={8'd0,gx}; sa=bs; sb=sp; end
