    if(jset) buf1[buf_wa]<=vsat; else buf0[buf_wa]<=vsat;
end
always @(posedge clk or posedge rst) begin
    if(rst) begin
        c0<=0; kp0<=0; l0<=0; cy<=0; ly<=0; row_ok<=0; fade_l<=0;
        kb0<=0; kb1<=0; tn0<=0; tn1<=0; ex0<=0; ex1<=0;
        kp<=0; col<=0; ptr<=0;
        st<=0; jcell<=0; jset<=0; pend<=0; pcell<=0; pset<=0;
        h1<=0; h2<=0; jex<=0; spark<=0; ox_q4<=0; oy<=0;
        bri<=0; beff<=0; bc<=0; bs<=0; tint<=0; ady<=0; dy0<=0; kb<=0; e<=0;
    end else begin
        if(frame_load) begin
            c0<=sx0>>(CELL_BITS+4);
            kp0<=(sx0>>4)&(CELL-1);
            l0<=sx0[3:0];
        end
        // pixel state
        if(line_prep) begin
            kp<=kp0; col<=c0; ptr<=0;
            cy<=y>>CELL_BITS; ly<=y&(CELL-1); row_ok<=(y>>CELL_BITS)<ROWS; fade_l<=fade;
            st<=5'd1; jcell<=c0; jset<=0;
            pend<=1; pcell<=(c0==NCELL-1) ? 7'd0 : c0+1'b1; pset<=1;
        end else begin
            if(de) begin
                kp<=n_kp; ptr<=n_ptr;
                if(last_px) begin
                    col<=col_inc;
                    // the slot just left now receives the cell after next
                    pend<=1; pset<=ptr;
                    pcell<=(col_inc==NCELL-1) ? 7'd0 : col_inc+1'b1;
                end
            end
            // job sequencer
            case(st)
                5'd0: if(pend) begin st<=5'd1; jcell<=pcell; jset<=pset; pend<=0; end
                5'd1, 5'd2: st<=st+1'b1;
                5'd3: begin h1<=h1w; st<=5'd4; end
                5'd4: begin
                    h2<=h2w;
                    jex<=row_ok && h1[15:12]<DENS;
                    ox_q4<=OXB+(NEAR ? {1'b0,h1[11:4]} : {2'd0,h1[11:5]});
                    oy<=(NEAR ? 5'd8 : 5'd4)+(NEAR ? {1'b0,h1[3:0]} : {2'd0,h1[2:0]});
                    tint<=h2w[9:8];
                    st<=5'd5;
                end
                5'd5: begin
                    // brightness from a squared hash: many faint, few bright
                    if(NEAR) bri<=({1'b0,8'd70}+{1'b0,prod[15:8]}-{4'd0,prod[15:11]})>9'd255 ? 8'd255 :
                                  8'd70+prod[15:8]-{3'd0,prod[15:11]};
                    else     bri<=8'd34+{1'b0,prod[15:9]}-{3'd0,prod[15:11]};
                    spark<=NEAR && h2[15:14]==2'b11 && prod[15:14]==2'b11;
                    ady<=dy[6] ? -dy[5:0] : dy[5:0];
                    dy0<=dy==0;
                    st<=5'd6;
                end
                5'd6: begin
                    kb<=kc_num[8:4]-R;
                    if(!jex || ady>R) begin
                        if(jset) begin ex1<=0; tn1<=tint; end else begin ex0<=0; tn0<=tint; end
                        st<=5'd0;
                    end else st<=5'd7;
                end
                5'd7: begin beff<=prod[15:8]; st<=5'd8; end
                5'd8: begin
                    bc<=prod[15:8]; bs<=spark ? sprod[15:8] : 8'd0; e<=0; st<=5'd9;
                    if(jset) begin kb1<=kb; tn1<=tint; ex1<=1; end
                    else     begin kb0<=kb; tn0<=tint; ex0<=1; end
                end
                default: begin
                    // st 9..9+NB: issue entry e; buf_we writes entry e-1
                    if(st==5'd9+NB) st<=5'd0;
                    else begin st<=st+1'b1; e<=e+1'b1; end
                end
            endcase
        end
    end
end
endmodule
